Na DummyJSON, `/todos/2` responde `{ id: 2, todo: 'Memorize a poem', completed: true, userId: 13 }`, `/todos/4` responde `{ id: 4, todo: 'Watch a documentary', completed: false, userId: 84 }`, e a tarefa 9999 não existe. Com internet, o que aparece no terminal?

```javascript
async function situacao(id) {
  const resposta = await fetch(`https://dummyjson.com/todos/${id}`);
  if (!resposta.ok) {
    return `Erro ${resposta.status}`;
  }
  const tarefa = await resposta.json();
  return tarefa.completed ? 'feita' : 'pendente';
}
async function mostrar() {
  console.log(await situacao(2), await situacao(4), await situacao(9999));
}
mostrar();
```
